def objective(pos_logits, neg_logits, mode):
    # Inputs contain only valid training positions.
    # neg_logits: [N, K], using the same eligible unique pool across controls.
    if mode == 'bce1':
        per_position = F.softplus(-pos_logits) + F.softplus(neg_logits[:, 0])
    elif mode == 'bce32':
        per_position = F.softplus(-pos_logits) + F.softplus(neg_logits).mean(dim=-1)
    elif mode == 'softmax32':
        logits = torch.cat((pos_logits[:, None], neg_logits), dim=-1)
        per_position = torch.logsumexp(logits, dim=-1) - pos_logits
    else:
        raise ValueError(mode)
    return per_position.mean()

